navbar_glassmorphism.css:
header .navbar {
  background-color: rgba(255, 255, 255, 0.9) !important;
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(0,0,0,0.05);
}
[data-bs-theme="dark"] header .navbar {
  background-color: rgba(0, 0, 0, 0.8) !important;
  border-bottom: 1px solid rgba(255,255,255,0.05);
}

card_portfolio_borderless.css:
.card-portfolio { border: none !important; background-color: transparent !important; border-radius: 0; }
.card-portfolio .img-wrapper { border-radius: 12px; overflow: hidden; margin-bottom: 1.5rem; }
.card-portfolio img { transition: transform 0.6s cubic-bezier(0.165, 0.84, 0.44, 1); }
.card-portfolio:hover img { transform: scale(1.05); }
.card-portfolio-title { font-size: 1.5rem; font-weight: 800; color: var(--sd-text); letter-spacing: -0.5px; }

botao_neon.css:
.btn-neon {
  background-color: var(--sd-primary); color: #000 !important; font-weight: 800;
  border-radius: 0; padding: 12px 30px; text-transform: uppercase; letter-spacing: 1px;
  border: 2px solid var(--sd-primary); transition: all 0.3s ease;
}
.btn-neon:hover {
  background-color: transparent; color: var(--sd-primary) !important;
  box-shadow: 0 0 20px rgba(0, 229, 255, 0.3);
}

scroll_to_top_square.css:
#btnScrollToTop {
  position: fixed; bottom: 30px; right: 30px; width: 50px; height: 50px;
  border-radius: 0; display: flex; align-items: center; justify-content: center;
  z-index: 1050; opacity: 0; visibility: hidden; transform: translateY(30px);
  background-color: var(--sd-dark); border: 2px solid var(--sd-primary); color: var(--sd-primary); cursor: pointer;
  transition: all 0.3s ease;
}
#btnScrollToTop.show { opacity: 1; visibility: visible; transform: translateY(0); }
#btnScrollToTop:hover { background-color: var(--sd-primary); color: #000; box-shadow: 0 0 15px rgba(0, 229, 255, 0.5); }

video_responsivo.css:
.mag-video-wrapper {
  position: relative; width: 100%; padding-bottom: 56.25%;
  height: 0; border-radius: 12px; overflow: hidden;
  box-shadow: 0 8px 25px rgba(0,0,0,0.08); margin: 2rem 0;
  background-color: #000;
}
.mag-video-wrapper iframe { position: absolute; top: 0; left: 0; width: 100%; height: 100%; border: none; }

javascript:
document.addEventListener('DOMContentLoaded', () => {
  'use strict';

  /* Dark Mode */
  const getStoredTheme = () => localStorage.getItem('theme');
  const setStoredTheme = theme => localStorage.setItem('theme', theme);
  const getPreferredTheme = () => {
    const storedTheme = getStoredTheme();
    if (storedTheme) return storedTheme;
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  };

  const setTheme = theme => {
    document.documentElement.setAttribute('data-bs-theme', theme);
    atualizarIcone(theme);
  };

  const atualizarIcone = (theme) => {
    const btnIcone = document.querySelector('.btn-dark-mode i');
    if (btnIcone) {
      btnIcone.className = theme === 'dark' ? 'bi bi-sun-fill text-warning' : 'bi bi-moon-stars-fill';
    }
  };

  setTheme(getPreferredTheme());

  window.alternarTema = () => {
    const temaAtual = document.documentElement.getAttribute('data-bs-theme');
    const novoTema = temaAtual === 'dark' ? 'light' : 'dark';
    setStoredTheme(novoTema);
    setTheme(novoTema);
  };

  document.querySelectorAll('.btn-dark-mode').forEach(btn => {
    btn.addEventListener('click', window.alternarTema);
  });

  /* Animacoes de Scroll */
  const observerOptions = { root: null, rootMargin: '0px', threshold: 0.1 };
  const scrollObserver = new IntersectionObserver((entries, observer) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        observer.unobserve(entry.target);
      }
    });
  }, observerOptions);

  document.querySelectorAll('.animate-up').forEach((el, index) => {
    if (el.classList.contains('card-portfolio')) {
      el.style.transitionDelay = `${(index % 2) * 0.15}s`;
    }
    scrollObserver.observe(el);
  });

  /* Scroll To Top */
  const btnScroll = document.getElementById('btnScrollToTop');
  window.addEventListener('scroll', () => {
    if (window.scrollY > 400) btnScroll.classList.add('show');
    else btnScroll.classList.remove('show');
  });
  btnScroll.addEventListener('click', () => window.scrollTo({ top: 0, behavior: 'smooth' }));
});
